export function FocusIndicator({
  label = "{{label}}",
  style = "{{style}}",
  accent = "{{accent}}",
  thickness = {{thickness}},
  showFocus = {{showFocus}},
}) {
  const active = {
    outline: { outline: thickness + "px solid " + accent, outlineOffset: 2 },
    glow: { boxShadow: "0 0 0 " + thickness + "px " + accent + ", 0 0 16px " + accent },
    underline: { boxShadow: "0 " + thickness + "px 0 0 " + accent },
  }[style];
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <button type="button" style={{ padding: "12px 22px", borderRadius: 8, border: "2px solid " + accent, background: "#FAF7F2", fontWeight: 600, cursor: "pointer", ...(showFocus ? active : {}) }}>{label}</button>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430aa" }}>{showFocus ? "shown as if keyboard-focused (Tab)\u2014outline never removed" : "outline: none with nothing in its place \u2014 keyboard users lose their place"}</p>
    </div>
  );
}
